{
  "requirements": [
    {
      "text": "The system shall continuously monitor the health of all primary sensors (camera, radar, ultrasonic) and, upon detection of degradation or failure, immediately transition to a safe state by disengaging Autopilot, providing a clear driver alert, and maintaining vehicle control using fallback strategies."
    },
    {
      "text": "The system shall enforce driver engagement by detecting hands‑on‑wheel presence, issuing escalating visual and audible warnings if engagement is lost, and automatically disengaging Autopilot if the driver does not respond within a defined time interval."
    },
    {
      "text": "The system shall implement a forward‑collision mitigation function that, independent of driver input, applies emergency braking when the time‑to‑collision falls below a certified threshold, meeting defined deceleration performance under all operating conditions."
    },
    {
      "text": "The system shall limit Autosteer steering torque to keep the vehicle’s lateral position within a maximum deviation of 0.3 m from the lane centerline and shall disengage Autosteer with a driver alert if this limit is exceeded or cannot be maintained."
    },
    {
      "text": "The system shall detect insufficient or ambiguous lane‑marking information and, in such situations, gracefully disengage Autosteer while providing an immediate driver notification and retaining speed‑control functions only if safe."
    },
    {
      "text": "The system shall maintain a minimum safe following distance based on a configurable time‑gap (e.g., 2.0 seconds) and shall never allow TACC to close the gap below this limit, adjusting speed proactively under all traffic‑flow variations."
    },
    {
      "text": "The system shall be developed and verified in compliance with ISO 26262 functional‑safety standards, including defined ASIL assignments, safety goals, and documented safety‑case evidence for all safety‑critical functions."
    },
    {
      "text": "The system shall provide a standardized driver hand‑over procedure that includes a distinct audible tone, visual cue, and a mandatory driver response window before any automated function is resumed after disengagement."
    },
    {
      "text": "The system shall securely record a continuous event log containing raw sensor data, processed perception outputs, driver‑monitoring status, and all system state transitions for post‑incident analysis."
    },
    {
      "text": "The system shall maintain functional performance within defined limits under adverse environmental conditions (rain, fog, glare, snow, electromagnetic interference) and shall degrade gracefully, alerting the driver and disengaging automated features when performance falls below safety thresholds."
    }
  ]
}
